// TH15 Extra (rank4) st07 MainSub03 wave: GirlA02 five round trips.
// Source: st07.ecl.txt:1178-1204 (entry), 154-217 (dependency).
// Card frame 0 = selected MainSub03 entry; opening buffer puts the source attack at ~card 120.
// TIME_LIMIT = 120 buffer + 1600 window + 4 startup margin (task-provided estimate, no native limit).

const TIME_LIMIT: int = 1724;
const OPENING_BUFFER: int = 120;

// Source GirlA02_at2 (198-217): aimed single shots, two per enemy, 40 frames apart.
async sub girl_at2() {
    for shot in 0..2 {
        sh_reset(0);
        sh_sprite(0, TH15_BALL, 6);      // etSprite(0,4,6): type4 -> TH15_BALL
        sh_ring(0, 0);                   // etAim(0,0): aimed fan
        sh_aim(0, 1);
        sh_count(0, 1, 1);               // etCount(0,1,1)
        sh_angle(0, 0deg, 3deg);         // etAngle(0,0,0.05235988) with N=1 -> alpha only
        sh_speed(0, 4.2fx, 0fx);         // etSpeed(0,4.2,2.2) with M=1 -> 4.2
        // EX ANIM a=1: position -= 4*velocity (native -4 * 4.2), born-side displacement only.
        sh_dist(0, -16.8fx);
        sh_fire(0);
        wait(40);
    }
}

// Source GirlA02F (165-182) plus GirlA02 (154-163).
// enmCreateM leaves the child mirror bit set. Ordinary moveVel angles are mirrored in that state
// (TH16 enemy-state.md §3, circular-motion.md end note); target has no mirror flag, so the
// horizontal reflection pi-angle is written explicitly. Spawn x is unaffected (parent mirror off).
async sub girl() {
    set_invuln(65535);
    set_hurtbox(12fx);                   // setHurtbox(24,24) -> radius 12
    set_hitbox(8fx);                     // setHitbox(16,16) -> radius 8
    var f2: angle = atan2(448fx - $self_y, 0fx - $self_x);  // getAngle(...,0,448)
    var travel: angle = 180deg - f2;      // mirror(pi) of the stored target angle
    move_vel(0, 90deg, 1fx, EASE_LINEAR); // moveVel(1.5707964,1.0)
    move_vel(60, travel, 2fx, EASE_LINEAR); // moveVelTime(60,0,F2,2.0)
    spawn girl_at2();                    // @GirlA02_at2() async
    // setDeath("GirlA02_at") is unreachable in the invincible shell and has no target API.
    wait(120);
    loop { wait(1000); }                 // GirlA02F_304/GirlA02F_324
}

// Source MainSub03 (1178-1204): 5 rounds, each 10 spawns left->right then 10 right->left,
// 10-frame interval, B from -120 by +24 then from +120 by -24.
async sub pattern() {
    wait(OPENING_BUFFER);
    for round in 0..5 {
        var b: fx = -120fx;
        for i in 0..10 {
            _ = spawn_enemy(b, -24fx, 70, 0, 0, 0, girl);   // enmCreateM("GirlA02",B,-24,70,1000,1)
            b = b + 24fx;
            wait(10);
        }
        for j in 0..10 {
            _ = spawn_enemy(b, -24fx, 70, 0, 0, 0, girl);
            b = b - 24fx;
            wait(10);
        }
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
